// Writes the Drizzle tables Better Auth expects, generated by its own Drizzle
// adapter from the options the server runs with, to
// src/workspace/infrastructure/auth-schema.generated.ts. Run it after changing
// those options or upgrading Better Auth, then `nx run acme-server:db:generate`
// for the migration. With --check it writes nothing and fails when the file
// is out of date.
import path from "node:path";

import { drizzle } from "drizzle-orm/node-postgres";
import { Option, Redacted } from "effect";
import { format } from "oxfmt";

import { makeAuth } from "#workspace/infrastructure/auth/options.ts";

import oxfmtConfig from "../../../oxfmt.config.ts";

const target = path.join(
  import.meta.dirname,
  "..",
  "src",
  "workspace",
  "infrastructure",
  "auth-schema.generated.ts"
);

const ignore = () => {
  // Generating the schema sends nothing and logs nothing.
};

// Nor does it bill anyone.
const nothing = async (): Promise<void> => {
  await Promise.resolve();
};

// Tables depend on the plugins and the options that shape columns, never on
// these settings, which only need to be valid. Billing is on, so the tables
// include Stripe's: a server without billing has them too, unused.
const auth = makeAuth({
  database: { db: drizzle.mock(), tables: {} },
  hooks: {
    invitation: ignore,
    log: ignore,
    memberAllowance: async () => await Promise.resolve(Option.none()),
    resetPassword: ignore,
    subscriptionChanged: nothing,
    verifyEmail: ignore,
  },
  settings: {
    captcha: Option.none(),
    databasePoolMax: 1,
    dynamicClientRegistration: true,
    ipAddressHeaders: ["x-forwarded-for"],
    production: false,
    publicUrl: "http://localhost:3001",
    requireEmailVerification: true,
    secret: Redacted.make("auth-schema-generator-only-0123456789abcdef"),
    stripe: Option.some({
      apiUrl: Option.none(),
      automaticTax: false,
      prices: { business: "price_schema_only", pro: "price_schema_only" },
      secretKey: Redacted.make("sk_test_schema_only"),
      webhookSecret: Redacted.make("whsec_schema_only"),
    }),
    trustedOrigins: [],
    trustedProxies: [],
  },
});

const context = await auth.$context;

const created = await context.adapter.createSchema?.(context.options, target);

if (created === undefined) {
  throw new Error("The Drizzle adapter no longer generates schemas");
}

// Better Auth writes dates as timestamp without time zone. Acme stores every
// instant as timestamptz. Checked, so a generator change that stops matching
// fails here instead of leaving plain timestamps. The generator formats its
// output with Prettier when it finds it installed, which changes the quotes.
const timestamp = /timestamp\((?<quote>["'])(?<column>[a-z_]+)\k<quote>\)/gu;

if (created.code.match(timestamp) === null) {
  throw new Error("The generated schema has no timestamp column to convert");
}

const code = await format(
  target,
  [
    "// Generated by scripts/auth-schema.ts from the Better Auth options in",
    "// src/workspace/infrastructure/auth/options.ts. Do not edit.",
    created.code.replaceAll(
      timestamp,
      `timestamp("$<column>", { withTimezone: true })`
    ),
  ].join("\n"),
  oxfmtConfig
);

if (code.errors.length > 0) {
  throw new Error(code.errors.map((error) => error.message).join("\n"));
}

const file = Bun.file(target);

const current = (await file.exists()) ? await file.text() : "";

if (process.argv.includes("--check")) {
  if (current !== code.code) {
    process.stderr.write(
      "The Better Auth schema is out of date: run nx run acme-server:auth-schema\n"
    );
    process.exit(1);
  }
} else if (current !== code.code) {
  await Bun.write(target, code.code);
  process.stdout.write(`${path.relative(process.cwd(), target)}\n`);
}
